function initialState(){return {screen:'intro',mission:0,stage:0,step:0,tries:0,score:0,integrity:100,lives:3,streak:0,maxStreak:0,completed:0,missed:0,missionScores:[0,0,0,0,0,0],missionHits:[0,0,0,0,0,0],finished:[],selectedCard:null,sorted:new Set(),promptSelected:new Set(),formValues:{},experimentRan:false,releaseRan:false,releaseChoice:null,toast:null,startAt:null,finishedAt:null,lessons:[],badges:[]};}
let state=initialState();
let runTimer=null;
function escapeHTML(text){return String(text ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function secs(){return state.startAt?Math.max(0,Math.round(((state.finishedAt||Date.now())-state.startAt)/1000)):0;}
function duration(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function pct(v,t){return t?Math.round(v/t*100):0;}
function gauge(value,variant=''){return `<div class="meter ${variant}" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(value)}"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;}
function notify(kind,title,text){state.toast={kind,title,text};}
function logLesson(text){if(text&&!state.lessons.includes(text))state.lessons.push(text);}
function award(correct,why,move){
  const tries=state.tries;
  if(correct){
    const gain=Math.max(40,100-tries*30);
    state.score+=gain;state.missionScores[state.mission]+=gain;state.missionHits[state.mission]++;
    state.completed++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);
    state.integrity=Math.min(100,state.integrity+2);
    if(state.streak!==0&&state.streak%5===0){state.lives=Math.min(3,state.lives+1);notify('good',`Combo ×${state.streak} !`,`${why} Bonus : récupération d’un bouclier.`);}else{notify('good',`+${gain} XP • Vérification réussie`,why);}
    logLesson(why);state.tries=0;move();render();return;
  }
  state.tries++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.integrity=Math.max(0,state.integrity-5);
  if(state.tries>=3){state.completed++;state.missed++;state.tries=0;logLesson(why);notify('bad','Correction révélée après 3 essais',why);move();render();return;}
  notify('bad',`Réponse à réviser — essai ${state.tries}/3`,`Ce choix ne satisfait pas les règles attendues. Relis l’énoncé et vérifie les préconditions, les limites et les résultats observables. Une erreur coûte un bouclier et 5 points d’intégrité.`);
  render();
}
function finishMission(){
  if(!state.finished.includes(state.mission))state.finished.push(state.mission);
  const badges=['🧭 Stratège QA','🔺 Architecte des tests','🧩 Maître Gherkin','🐞 Chasseur de bogues','🤖 Auditeur IA','🚀 Gardien du déploiement'];
  state.badges.push(badges[state.mission]);state.screen='missionComplete';state.lives=3;
  if(state.mission===5)state.finishedAt=Date.now();
  notify('good','Mission accomplie',`Badge débloqué : ${badges[state.mission]}.`);
}
function nextStage(){state.stage++;state.step=0;state.tries=0;state.formValues={};state.selectedCard=null;state.sorted=new Set();state.experimentRan=false;state.releaseRan=false;state.releaseChoice=null;}
function step(){state.step++;state.tries=0;state.formValues={};state.experimentRan=false;state.releaseRan=false;state.releaseChoice=null;}
function moveSort(cardId,count){state.sorted.add(cardId);state.selectedCard=null;if(state.sorted.size===count)nextStage();}
function answerSort(category){
  const items=state.mission===0?strategy:pyramids;
  const card=items.find(c=>c.id===state.selectedCard);
  if(!card){notify('neutral','Sélectionne une carte','Clique sur une carte, puis sur sa catégorie. Tu peux aussi la glisser-déposer.');render();return;}
  award(card.cat===category,card.why,()=>moveSort(card.id,items.length));
}
function answerQuiz(index){const arr=state.mission===0?quiz1:state.mission===1?quiz2:quiz3;const q=arr[state.step];award(Number(index)===q.correct,q.why,()=>{step();if(state.step>=arr.length)finishMission();});}
function answerGherkin(){const scenario=gherkinScenarios[state.step];const values=['given','when','then'].map(id=>Number(document.getElementById(`gherkin-${id}`)?.value));if(values.some(v=>!Number.isFinite(v)||v<0)){notify('bad','Champs incomplets','Sélectionne une proposition pour chaque ligne Étant donné, Lorsque et Alors.');render();return;}
  const right=values.every((v,i)=>v===scenario.answers[i]);award(right,scenario.why,()=>{step();if(state.step>=gherkinScenarios.length)nextStage();});}
function answerExperiment(answer){if(!state.experimentRan){notify('neutral','Exécute le scénario','Observe d’abord le résultat affiché par l’application fictive.');render();return;}const t=simulatedCases[state.step];award(answer===t.actual,t.why,()=>{step();if(state.step>=simulatedCases.length)nextStage();});}
function answerReport(){const t=bugReports[state.step];const values=t.fields.map((_,i)=>Number(document.getElementById('report-field-'+i)?.value));if(values.some(v=>v<0||!Number.isFinite(v))){notify('bad','Rapport incomplet','Remplis les quatre champs de ton rapport.');render();return;}const correct=values.every((v,i)=>v===t.fields[i].answer);award(correct,t.why,()=>{step();if(state.step>=bugReports.length)finishMission();});}
function answerPrompt(){const good=aiPromptOptions.filter(x=>x.good).map(x=>x.id);if(state.promptSelected.size!==5){notify('bad','Sélection incomplète','Choisis exactement cinq consignes utiles pour un prompt QA responsable.');render();return;}const valid=good.every(id=>state.promptSelected.has(id));award(valid,'Un prompt fiable explicite le contexte, les règles, les cas, les résultats attendus et les contraintes de sécurité.',()=>nextStage());}
function answerReview(index){const t=aiReviews[state.step];award(Number(index)===t.correct,t.why,()=>{step();if(state.step>=aiReviews.length)finishMission();});}
function answerRisk(value){const t=risks[state.step];award(value===t.level,t.why,()=>{step();if(state.step>=risks.length)nextStage();});}
function answerRelease(){if(!state.releaseRan){notify('bad','Pipeline non simulé','Lance d’abord la simulation de pipeline CI/CD.');render();return;}if(!state.releaseChoice){notify('bad','Décision manquante','Choisis GO ou NO-GO.');render();return;}const reason=Number(document.getElementById('release-reason')?.value);if(reason<0||!Number.isFinite(reason)){notify('bad','Justification manquante','Choisis également une raison pour ta décision.');render();return;}const t=releases[state.step];award(state.releaseChoice===t.decision&&reason===t.rationale,t.why,()=>{step();if(state.step>=releases.length)finishMission();});}
function startGame(){state=initialState();state.startAt=Date.now();state.screen='playing';render();}
function advanceMission(){if(state.mission===5){state.screen='results';state.toast=null;}else{state.mission++;state.stage=0;state.step=0;state.tries=0;state.lives=3;state.selectedCard=null;state.sorted=new Set();state.promptSelected=new Set();state.formValues={};state.experimentRan=false;state.releaseRan=false;state.releaseChoice=null;state.screen='playing';state.toast=null;}render();window.scrollTo({top:0,behavior:'smooth'});}
function rank(){const x=pct(state.score,TOTAL*100);if(x>=90)return 'LÉGENDE QA — OR';if(x>=75)return 'COMMANDANT QA — ARGENT';if(x>=60)return 'EXPERT QA — BRONZE';return 'AGENT QA — EN PROGRESSION';}
function svgHero(){return `<svg class="robot-scene" viewBox="0 0 370 350" role="img" aria-label="Illustration d’un robot QA cyberpunk surveillant des panneaux de tests lumineux"><defs><linearGradient id="hb" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#74f7ff"/><stop offset="1" stop-color="#a378fb"/></linearGradient><radialGradient id="glow"><stop stop-color="#72e9ff" stop-opacity=".32"/><stop offset="1" stop-color="#4c8fff" stop-opacity="0"/></radialGradient></defs><circle cx="190" cy="170" r="158" fill="url(#glow)"/><g opacity=".47" stroke="#70d4ff" fill="none"><circle cx="193" cy="168" r="138" stroke-dasharray="8 11"/><circle cx="193" cy="168" r="110" stroke-dasharray="4 9"/><path d="M32 250H340M36 95H340M95 30V322M292 40V325" opacity=".28"/></g><g transform="translate(40 62)"><rect x="0" y="0" width="95" height="70" rx="8" fill="#142e51" stroke="#50d9ff" opacity=".9"/><text x="12" y="21" fill="#74f3ff" font-size="10" font-weight="bold">UNIT TESTS</text><path d="M12 32h65M12 41h47M12 50h57" stroke="#5cb8dd" stroke-width="3"/><circle cx="76" cy="57" r="7" fill="#4cf1b9"/></g><g transform="translate(248 64)"><rect x="0" y="0" width="92" height="86" rx="9" fill="#1a2353" stroke="#a68aff"/><text x="10" y="24" fill="#d2c5ff" font-size="11">CI / CD</text><path d="M11 40h70M11 52h70M11 64h42" stroke="#a68aff" stroke-width="4" opacity=".7"/><path d="m59 64 9 9 15-18" stroke="#72efbd" stroke-width="4" fill="none"/></g><g transform="translate(95 98)"><ellipse cx="98" cy="229" rx="108" ry="20" fill="#112d52" stroke="#61d7ff"/><rect x="61" y="125" width="78" height="98" rx="24" fill="#1d4071" stroke="url(#hb)" stroke-width="4"/><rect x="15" y="140" width="41" height="80" rx="19" fill="#2e527d" stroke="#63cbf6" stroke-width="3"/><rect x="144" y="140" width="41" height="80" rx="19" fill="#2e527d" stroke="#63cbf6" stroke-width="3"/><rect x="52" y="25" width="97" height="120" rx="36" fill="#9ebbf5" stroke="#67e5ff" stroke-width="5"/><rect x="63" y="51" width="75" height="61" rx="22" fill="#0a1c37"/><ellipse cx="85" cy="81" rx="9" ry="14" fill="#5bedff"/><ellipse cx="117" cy="81" rx="9" ry="14" fill="#5bedff"/><path d="M90 100q11 9 22 0" stroke="#62efc6" stroke-width="4" fill="none"/><rect x="92" y="1" width="15" height="29" rx="6" fill="#79bcf3"/><circle cx="99" cy="1" r="10" fill="#74efff"/><rect x="69" y="160" width="62" height="41" rx="9" fill="#0d2646" stroke="#8dc9ff"/><path d="m86 181 9 10 18-21" fill="none" stroke="#74efb4" stroke-width="7" stroke-linecap="round"/><rect x="67" y="215" width="25" height="24" rx="6" fill="#416eac"/><rect x="110" y="215" width="25" height="24" rx="6" fill="#416eac"/></g><g fill="#85f3ff" opacity=".85"><circle cx="27" cy="173" r="3"/><circle cx="331" cy="205" r="5"/><circle cx="243" cy="28" r="3"/></g></svg>`;}
function svgMission(n){
  const shapes=[
    '<circle cx="90" cy="80" r="49" stroke="#5be6ff" stroke-width="7"/><circle cx="90" cy="80" r="28" stroke="#ad8bff" stroke-width="5"/><circle cx="90" cy="80" r="8" fill="#62ffd0"/><path d="m92 80 42-42" stroke="#6cf4ff" stroke-width="8" stroke-linecap="round"/><path d="M123 29h24v23" stroke="#72e8ff" stroke-width="5" fill="none"/>',
    '<path d="M88 23 153 136H23Z" stroke="#69e6ff" stroke-width="5" fill="#112744"/><path d="M63 95h50L128 122H48Z" fill="#5be6ff88"/><path d="M49 118h78l12 20H37Z" fill="#5ee8ac88"/><path d="M75 58h26l19 32H56Z" fill="#b68cff99"/>',
    '<rect x="30" y="20" width="120" height="132" rx="13" fill="#102b52" stroke="#74dfff" stroke-width="4"/><path d="M53 53h74M53 80h74M53 109h74" stroke="#b28cff" stroke-width="5" stroke-linecap="round"/><path d="m47 52 5 6 12-13m-17 36 5 6 12-13m-17 36 5 6 12-13" stroke="#5ef3a9" stroke-width="4" fill="none"/>',
    '<path d="M72 42Q90 16 108 42M59 47 43 28m78 19 18-19M64 91l-30 11m82-11 30 11M62 118l-26 22m80-22 27 22" stroke="#a28aff" stroke-width="7" fill="none" stroke-linecap="round"/><ellipse cx="90" cy="89" rx="42" ry="57" fill="#172e50" stroke="#5be6ff" stroke-width="5"/><path d="M90 35v108M50 88h80" stroke="#78eac3" stroke-width="4"/><circle cx="74" cy="67" r="5" fill="#ff87b3"/><circle cx="105" cy="67" r="5" fill="#ff87b3"/>',
    '<rect x="33" y="43" width="114" height="100" rx="20" fill="#183a61" stroke="#6be8ff" stroke-width="5"/><rect x="48" y="61" width="83" height="55" rx="17" fill="#071b37"/><circle cx="70" cy="88" r="9" fill="#65e9ff"/><circle cx="108" cy="88" r="9" fill="#65e9ff"/><path d="m75 106 16 8 14-8" stroke="#79efa9" stroke-width="4" fill="none"/><path d="M89 39V22m0 0h24" stroke="#a88cff" stroke-width="6"/><circle cx="118" cy="22" r="7" fill="#be9aff"/>',
    '<path d="m89 19 30 72-30 19-30-19Z" fill="#1e4268" stroke="#75eaff" stroke-width="5"/><rect x="81" y="54" width="16" height="19" rx="8" fill="#6cf5ff"/><path d="m70 102-17 26m57-26 17 26" stroke="#b18dff" stroke-width="8" stroke-linecap="round"/><path d="m78 114-5 30 16-9 16 9-5-30" fill="#ffb56b"/><path d="m80 137-10 19 19-7 19 7-10-19" fill="#ff7595"/>'
  ];
  return `<svg class="mission-art" viewBox="0 0 180 175" role="img" aria-label="Illustration de la mission ${n+1}"><defs><radialGradient id="ms${n}"><stop stop-color="#4ccefb" stop-opacity=".28"/><stop offset="1" stop-color="#4ccefb" stop-opacity="0"/></radialGradient></defs><circle cx="90" cy="83" r="80" fill="url(#ms${n})"/><circle cx="90" cy="83" r="74" stroke="#9d85fa" stroke-dasharray="2 8" fill="none" opacity=".67"/><g>${shapes[n]}</g></svg>`;
}
function header(){return `<header class="topbar no-print"><div class="brand"><div class="brand-mark" aria-hidden="true">🛡️</div><div><div class="brand-text">QA <span>WARS</span></div><div class="brand-sub">Mission Zéro Bug • NEXUS</div></div></div><div class="top-hud"><div class="hud-chip"><span class="hud-glyph">⏱️</span><div><div class="small">Temps</div><strong id="timer">${duration(secs())}</strong></div></div><div class="hud-chip"><span class="hud-glyph">⚡</span><div><div class="small">Expérience</div><strong>${state.score.toLocaleString('fr-CA')} XP</strong></div></div><div class="hud-chip"><span class="hud-glyph">❤️</span><div><div class="small">Boucliers</div><strong>${'♥'.repeat(state.lives)}${'♡'.repeat(3-state.lives)}</strong></div></div><div class="hud-chip"><span class="hud-glyph">🛡️</span><div><div class="small">Intégrité</div><strong class="${state.integrity<40?'pink':'lime'}">${state.integrity}%</strong></div></div></div></header>`;}
function sidebar(){return `<aside class="sidebar no-print"><nav class="panel side-panel" aria-label="Carte des missions"><p class="side-title">CARTE DES OPÉRATIONS</p>${TITLES.map((t,i)=>`<div class="mission-link ${state.finished.includes(i)?'done':''} ${state.mission===i&&state.screen!=='intro'?'active':''}"><span class="micon">${state.finished.includes(i)?'✓':i>state.mission?'🔒':ICONS[i]}</span><div><span class="mtext">${escapeHTML(t)}</span><span class="mnum">${state.finished.includes(i)?'Mission accomplie':`Mission 0${i+1}${i>state.mission?' • verrouillée':''}`}</span></div></div>`).join('')}</nav><div class="panel side-status"><p class="side-title">CENTRE DE CONTRÔLE</p><div><div class="stat-row"><span>Progression</span><strong>${state.completed}/${TOTAL}</strong></div>${gauge(pct(state.completed,TOTAL))}</div><div><div class="stat-row"><span>Intégrité NEXUS</span><strong>${state.integrity}%</strong></div>${gauge(state.integrity,'orange')}</div><div><div class="stat-row"><span>Meilleur combo</span><strong>×${state.maxStreak}</strong></div><p class="fine-print">3 tentatives par défi. Une erreur retire un bouclier et 5 % d’intégrité. Les boucliers reviennent à chaque mission.</p></div></div></aside>`;}
function footer(){return `<footer class="footer no-print">QA WARS • Version ${VERSION} • Hors ligne • 6 missions • Sans son • Simulations pédagogiques, non connectées à un compilateur ou à un serveur.</footer>`;}
function viewIntro(){return `<section class="hero"><div><span class="pill"><span class="live"></span> ALERTE NEXUS / OPÉRATION ACTIVE</span><h1>MISSION<br><em>ZÉRO BUG</em></h1><p>Le lancement de NEXUS approche. Le système accumule des anomalies. Entre dans le centre de contrôle, bâtis ta stratégie QA, débusque les défauts et prends la décision finale : <strong>GO ou NO-GO ?</strong></p><div class="btn-row"><button class="btn btn-primary" data-action="start">⚡ DÉMARRER LA MISSION →</button><span class="muted" style="font-size:12px">35–45 min • Individuel • Intermédiaire</span></div><div class="hero-chips"><span class="micro-chip">◈ 6 MISSIONS</span><span class="micro-chip">◈ 47 DÉFIS</span><span class="micro-chip">◈ 100 % HORS LIGNE</span></div></div><div>${svgHero()}</div></section><div class="section-heading"><h2>⚙️ Votre arsenal de tests</h2><span class="micro">BASÉ SUR LES 26 DIAPOSITIVES DU COURS</span></div><div class="brief-grid"><article class="brief-card"><div class="emoji">🎯</div><strong>Stratégie & risques</strong><p>Cadrer, préparer et prioriser une campagne QA.</p></article><article class="brief-card"><div class="emoji">🧪</div><strong>Tests & acceptation</strong><p>Unitaires, intégration, E2E, Gherkin et DoD.</p></article><article class="brief-card"><div class="emoji">🤖</div><strong>IA & déploiement</strong><p>Vérifier les tests générés, pipeline et décision de livraison.</p></article></div><p class="intro-notice">🎮 Utilisation : souris ou clavier. Pour glisser-déposer, tu peux aussi sélectionner une carte puis cliquer sur la catégorie. La partie n’est pas sauvegardée à la fermeture de la page.</p>`;}
function missionHeading(){return `<section class="mission-hero"><div class="copy"><span class="eyebrow">MISSION ${String(state.mission+1).padStart(2,'0')} / 06 — ${state.mission===5?'BOSS FINAL':'SYSTÈME DE FORMATION QA'}</span><h1>${ICONS[state.mission]} ${escapeHTML(TITLES[state.mission])}</h1><p>${escapeHTML(SUBTITLES[state.mission])}</p></div>${svgMission(state.mission)}</section>`;}
function strip(labels){return `<div class="stage-strip" aria-label="Progression de la mission">${labels.map((t,i)=>`<div class="stage-tag ${state.stage>i?'done':state.stage===i?'current':''}">${state.stage>i?'✓':i+1} ${escapeHTML(t)}</div>`).join('<span style="color:#5b7498">→</span>')}</div>`;}
function workspace(title,desc,body,count=''){return `<section class="panel workspace"><div class="workspace-heading"><div><span class="eyebrow">SIMULATION INTERACTIVE</span><h2>${title}</h2><p>${desc}</p></div>${count?`<span class="step-count">${count}</span>`:''}</div>${body}</section>`;}
function feedbackBanner(){return `<div class="tipline">💡 <span><strong>Astuce de NEX-BOT :</strong> raisonne à partir des règles et du résultat observable. Une réponse correcte doit pouvoir être justifiée, pas simplement devinée.</span></div>`;}
function sortingView(items,targetList,title,desc){const remaining=items.filter(x=>!state.sorted.has(x.id));return workspace(title,desc,`<div class="cards-layout"><div class="card-bank"><div class="minihead">📦 Éléments à classer • ${remaining.length} restant(s)</div>${remaining.map(c=>`<div class="drag-card ${state.selectedCard===c.id?'selected':''}" draggable="true" tabindex="0" role="button" aria-pressed="${state.selectedCard===c.id}" data-card="${c.id}" title="Sélectionner ou glisser cette carte"><span class="card-symbol">${c.emoji}</span><span>${escapeHTML(c.name)}</span></div>`).join('')}<p class="selection-info">${state.selectedCard?`Carte choisie : <b>${escapeHTML(items.find(x=>x.id===state.selectedCard)?.name)}</b>`:'Clique sur une carte ou glisse-la.'}</p></div><div class="targets">${targetList.map(t=>`<button class="target" data-target="${t.id}"><strong>${escapeHTML(t.name)}</strong><span>${escapeHTML(t.desc)}</span></button>`).join('')}</div></div>${feedbackBanner()}`,`${items.length-remaining.length}/${items.length}`);}
function quizView(items,title){const q=items[state.step];return workspace(title,'Choisis la meilleure réponse. La formulation suit les définitions et exemples du cours.',`<div class="case-progress">${items.map((_,i)=>`<i class="${i<=state.step?'filled':''}"></i>`).join('')}</div><div class="question">${escapeHTML(q.q)}</div><div class="options">${q.a.map((answer,i)=>`<button class="option" data-quiz="${i}"><span class="letter">${LETTERS[i]}</span><span>${escapeHTML(answer)}</span></button>`).join('')}</div>${feedbackBanner()}`,`${state.step+1}/${items.length}`);}
function gherkinView(){const sc=gherkinScenarios[state.step];const groups=[{id:'given',label:'Étant donné',items:sc.given},{id:'when',label:'Lorsque',items:sc.when},{id:'then',label:'Alors',items:sc.then}];return workspace('Construire un scénario Gherkin','Sélectionne les conditions, l’action et le résultat attendu dans le bon ordre.',`<div class="summary-box"><strong>USER STORY :</strong> En tant que joueur authentifié, je veux acheter un kart avec mes pièces pour personnaliser mon garage.<div class="muted" style="margin-top:5px"><strong>${escapeHTML(sc.title)}</strong> — ${escapeHTML(sc.story)}</div></div><div class="three-grid">${groups.map(g=>`<div class="statement"><div class="statement-tag">${g.label}</div><div class="field"><label for="gherkin-${g.id}">Choisir la proposition</label><select id="gherkin-${g.id}"><option value="-1">— Choisir —</option>${g.items.map((v,i)=>`<option value="${i}">${escapeHTML(v)}</option>`).join('')}</select></div></div>`).join('')}</div><div class="btn-row" style="margin-top:16px"><button class="btn btn-primary" data-action="gherkin-check">✓ Valider le scénario</button></div>${feedbackBanner()}`,`${state.step+1}/${gherkinScenarios.length}`);}
function experimentView(){const c=simulatedCases[state.step];return workspace('Tester l’application NEXUS — Boutique de karts','Observe la vraie sortie de l’application fictive. Compare-la aux règles métier, puis prononce ton diagnostic.',`<div class="cart-screen"><div class="cart-top"><strong>🏎️ BOUTIQUE • ${escapeHTML(c.title)}</strong><span>● ENVIRONNEMENT QA</span></div><div class="cart-body"><div><div class="kart-figure" role="img" aria-label="Kart de course stylisé">🏎️</div><div class="cart-detail">Prix du kart : <strong>${c.price} pièces</strong></div></div><div><div class="cart-detail">Solde du joueur authentifié</div><div class="cart-value">${c.balance} 🪙</div><div class="cart-detail">Boutique / Garage : disponible</div><button class="btn btn-primary small" data-action="run-experiment" ${state.experimentRan?'disabled':''}>${state.experimentRan?'✓ Exécuté':'▶ Tester l’achat'}</button></div></div></div>${state.experimentRan?`<div class="terminal" aria-label="Résultat observé">&gt; simulation.AcheterKart(${c.price})<br>&gt; ${escapeHTML(c.observed)}<br><span class="cursor"></span></div><div class="btn-row" style="margin-top:15px"><button class="btn btn-secondary" data-diagnosis="Conforme">✅ Comportement conforme</button><button class="btn btn-danger" data-diagnosis="Anomalie">🐞 Anomalie détectée</button></div>`:'<div class="info-banner">Clique sur « Tester l’achat » pour révéler le comportement observé. Le logiciel peut contenir un bogue… ou être conforme !</div>'}${feedbackBanner()}`,`${state.step+1}/${simulatedCases.length}`);}
function reportView(){const b=bugReports[state.step];return workspace('Rédiger un rapport d’anomalie reproductible','Choisis un titre descriptif, l’impact, le résultat attendu et les étapes de reproduction.',`<div class="summary-box"><strong>🐞 ${escapeHTML(b.title)}</strong><div style="margin-top:5px">${escapeHTML(b.desc)}</div></div><div class="split">${b.fields.map((f,i)=>`<div class="field"><label for="report-field-${i}">${escapeHTML(f.name)}</label><select id="report-field-${i}"><option value="-1">— Choisir —</option>${f.options.map((o,j)=>`<option value="${j}">${escapeHTML(o)}</option>`).join('')}</select></div>`).join('')}</div><div class="btn-row" style="margin-top:14px"><button class="btn btn-primary" data-action="report-check">📋 Soumettre le rapport QA</button></div><p class="fine-print">Dans un vrai outil de suivi, ajoute aussi la version, l’environnement, les preuves et la priorité décidée avec l’équipe.</p>`,`${state.step+1}/${bugReports.length}`);}
function promptView(){return workspace('Construire un prompt QA efficace','NEX-BOT a besoin d’instructions pertinentes. Sélectionne exactement cinq éléments à transmettre à l’IA.',`<div class="split"><div class="note-panel"><h3>🤖 Demande reçue</h3><p>« Génère des tests xUnit pour l’achat de karts. »</p><p style="margin-top:12px">Sans règles ni exemples, le modèle risque de proposer des tests incorrects ou d’inventer un comportement.</p></div><div class="note-panel"><h3>🛡️ Objectif du prompt</h3><p>Protéger les données, couvrir les cas limites et fournir des assertions vérifiables par un humain.</p><p style="margin-top:12px"><strong class="cyan">${state.promptSelected.size}/5 consignes choisies</strong></p></div></div><div class="section-heading"><h2>Choisir les consignes</h2></div><div class="prompt-options">${aiPromptOptions.map(x=>`<button class="prompt-opt ${state.promptSelected.has(x.id)?'selected':''}" data-prompt="${x.id}" aria-pressed="${state.promptSelected.has(x.id)}"><span class="check">${state.promptSelected.has(x.id)?'✓':''}</span><span>${escapeHTML(x.text)}</span></button>`).join('')}</div><div class="btn-row" style="margin-top:16px"><button class="btn btn-primary" data-action="prompt-check">🤖 Soumettre le prompt</button></div>${feedbackBanner()}`,'1/1');}
function codeHTML(code){return escapeHTML(code).replace(/\b(public|void|var|new|return|class)\b/g,'<span class="keyword">$1</span>').replace(/\b(Assert|AcheterKart|Fact|Boutique)\b/g,'<span class="method">$1</span>').replace(/(\/\/[^\n]*)/g,'<span class="comment">$1</span>');}
function reviewView(){const a=aiReviews[state.step];return workspace('Auditer un test proposé par l’IA','Lis cet extrait conceptuel de C# / xUnit. Les exemples ne sont pas compilés ici.',`<div class="code-shell"><div class="code-bar"><span>NEX-BOT / ${escapeHTML(a.title)}</span><span>SIMULATION</span></div><pre><code>${codeHTML(a.code)}</code></pre></div><div class="question">${escapeHTML(a.q)}</div><div class="options">${a.a.map((s,i)=>`<button class="option" data-review="${i}"><span class="letter">${LETTERS[i]}</span><span>${escapeHTML(s)}</span></button>`).join('')}</div>`,`${state.step+1}/${aiReviews.length}`);}
function riskView(){const t=risks[state.step];return workspace('Matrice des risques — choisir les priorités','Tu ne peux pas tout tester : compare la probabilité de défaillance et l’impact.',`<div class="risk-head"><strong>${escapeHTML(t.feature)}</strong><span>Cas ${state.step+1}/4</span></div><div class="risk-grid"><div class="risk-cell m"><small>Fonctionnalité</small><strong>${escapeHTML(t.feature)}</strong></div><div class="risk-cell h"><small>Probabilité</small><strong>${escapeHTML(t.prob)}</strong></div><div class="risk-cell h"><small>Impact</small><strong>${escapeHTML(t.impact)}</strong></div></div><div class="question">Quelle priorité donnerais-tu aux tests de cette fonctionnalité ?</div><div class="options">${['Très haute','Moyenne','Basse','Aucune'].map((v,i)=>`<button class="option" data-risk="${escapeHTML(v)}"><span class="letter">${LETTERS[i]}</span><span>${escapeHTML(v)}</span></button>`).join('')}</div><p class="fine-print">La matrice utilise les priorités illustratives du document de cours, pas une formule universelle.</p>`,`${state.step+1}/${risks.length}`);}
function pipelineView(){const r=releases[state.step];return workspace('BOSS FINAL — Décision GO / NO-GO','Exécute la pipeline fictive, inspecte ses contrôles, choisis une décision ET une justification.',`<div class="summary-box"><strong>🚀 ${escapeHTML(r.title)}</strong><div class="muted">Tests, risques résiduels, sécurité et validation métier doivent être considérés ensemble.</div></div><div class="pipeline">${r.checks.map((ch,i)=>`<div class="pipeline-row ${state.releaseRan?'':'running'}"><span>${escapeHTML(ch[0])}</span>${state.releaseRan?`<span class="muted">${escapeHTML(ch[1])}</span><span class="status ${ch[2]}">${ch[2]==='pass'?'✓ PASS':ch[2]==='fail'?'✕ FAIL':'! À SUIVRE'}</span>`:'<span class="status wait">EN ATTENTE</span>'}</div>`).join('')}</div><div class="btn-row" style="margin-top:14px"><button class="btn btn-secondary" data-action="run-release" ${state.releaseRan?'disabled':''}>${state.releaseRan?'✓ Simulation terminée':'▶ Exécuter la pipeline CI/CD'}</button></div>${state.releaseRan?`<div class="divider"></div><div class="question">Autorises-tu le déploiement ?</div><div class="choice-buttons"><button class="choice-btn ${state.releaseChoice==='GO'?'active':''}" data-release-choice="GO">✅ GO — livrer</button><button class="choice-btn ${state.releaseChoice==='NO-GO'?'active':''}" data-release-choice="NO-GO">⛔ NO-GO — bloquer</button></div><div class="field"><label for="release-reason">Pourquoi ? Choisis une justification.</label><select id="release-reason"><option value="-1">— Justification —</option>${r.reasons.map((reason,i)=>`<option value="${i}">${escapeHTML(reason)}</option>`).join('')}</select></div><button class="btn btn-primary" data-action="release-check">🔐 Valider la décision de livraison</button>`:'<div class="info-banner">Lance la pipeline pour révéler les résultats de la simulation. Aucune commande réelle n’est exécutée.</div>'}`,`${state.step+1}/${releases.length}`);}
function missionContent(){switch(state.mission){case 0:return strip(['Classer la stratégie','Questions expertes'])+(state.stage===0?sortingView(strategy,strategyTargets,'Bâtir une stratégie de tests','Classe les neuf éléments de la stratégie par leur fonction principale.'):quizView(quiz1,'Vérification de la stratégie'));case 1:return strip(['Pyramide des tests','Concepts modernes'])+(state.stage===0?sortingView(pyramids,pyramidTargets,'Choisir le bon niveau de test','Répartis les scénarios selon le niveau le plus adapté. La pyramide guide la répartition, pas un ordre obligatoire.'):quizView(quiz2,'Techniques, approches et qualités'));case 2:return strip(['Constructeur Gherkin','Acceptation et DoD'])+(state.stage===0?gherkinView():quizView(quiz3,'Métier, critères et collaboration'));case 3:return strip(['Tester et diagnostiquer','Rapports de bogues'])+(state.stage===0?experimentView():reportView());case 4:return strip(['Prompt responsable','Audit du code IA'])+(state.stage===0?promptView():reviewView());case 5:return strip(['Prioriser les risques','Décision de livraison'])+(state.stage===0?riskView():pipelineView());default:return '';}}
function viewPlaying(){return missionHeading()+missionContent()+`<div class="lesson"><strong>📚 Référence du cours :</strong><p>${[
'Une stratégie précise le périmètre, les moyens, les environnements, les anomalies, les tests, les données, les rôles et les échéances.',
'Les tests unitaires, d’intégration et E2E sont complémentaires. La pyramide est un guide de répartition.',
'Une User Story doit préciser les variantes, préconditions, règles d’affaires et résultats attendus. Gherkin est une spécification, pas une exécution automatique.',
'Un défaut doit être reproduit avec ses étapes, ses données, son résultat attendu et son résultat réel. Sévérité et priorité sont distinctes.',
'L’IA peut suggérer des tests, mais l’équipe doit contrôler les assertions, les règles métier, la confidentialité et l’exécution réelle.',
'Les tests continus, la priorisation selon les risques et les critères d’entrée/sortie rendent la décision de livraison plus fiable.'
][state.mission]}</p></div>`;}
function viewMissionComplete(){const m=state.mission;const hit=state.missionHits[m];return `${missionHeading()}<section class="panel complete-panel"><div class="victory-icon">${ICONS[m]}</div><span class="eyebrow">MISSION ${m+1} VALIDÉE</span><h2>PROTOCOLE TERMINÉ ✓</h2><p>${SUBTITLES[m]} Le centre de contrôle a enregistré tes réponses et les leçons utiles.</p><div class="complete-stats"><span>⚡ ${state.missionScores[m]} / ${COUNTS[m]*100} XP</span><span>✅ ${hit} / ${COUNTS[m]} défis réussis</span><span>🏅 ${escapeHTML(state.badges[state.badges.length-1])}</span></div><div class="btn-row" style="justify-content:center"><button class="btn btn-primary" data-action="next-mission">${m===5?'🏆 VOIR MON RAPPORT FINAL':'🚀 DÉVERROUILLER LA MISSION SUIVANTE →'}</button></div></section>`;}
function detailedAdvice(){const arr=[];if(state.missionScores[0]<COUNTS[0]*70)arr.push('Réviser les neuf éléments de la stratégie de tests et la différence sévérité / priorité.');if(state.missionScores[1]<COUNTS[1]*70)arr.push('Revoir la pyramide des tests, TDD, BDD et régression.');if(state.missionScores[2]<COUNTS[2]*70)arr.push('Retravailler Étant donné / Lorsque / Alors, les critères d’acceptation et la DoD.');if(state.missionScores[3]<COUNTS[3]*70)arr.push('S’entraîner à diagnostiquer les écarts et rédiger des anomalies reproductibles.');if(state.missionScores[4]<COUNTS[4]*70)arr.push('Auditer la qualité des assertions générées par IA et les consignes du prompt.');if(state.missionScores[5]<COUNTS[5]*70)arr.push('Approfondir la priorisation des risques et les décisions de mise en production.');return arr.length?arr:['Très bon travail ! Pour aller plus loin, transforme un scénario Gherkin en tests xUnit réellement exécutables et compare-les avec des résultats de CI/CD.'];}
function viewResults(){const result=pct(state.score,TOTAL*100);const advice=detailedAdvice();return `<section class="panel report print-report"><div class="report-header"><span class="eyebrow">CENTRE NEXUS • RAPPORT FINAL</span><h1>🏆 MISSION ZÉRO BUG</h1><div class="report-sub">Bilan individuel • ${new Date(state.finishedAt||Date.now()).toLocaleDateString('fr-CA')} • Durée : ${duration(secs())}</div><div class="badge-rank">${escapeHTML(rank())}</div></div><div class="report-stat-grid"><div class="report-stat"><strong>${state.score}</strong><small>XP / ${TOTAL*100}</small></div><div class="report-stat"><strong>${result}%</strong><small>Réussite pondérée</small></div><div class="report-stat"><strong>${TOTAL-state.missed}/${TOTAL}</strong><small>Défis résolus</small></div><div class="report-stat"><strong>${state.integrity}%</strong><small>Intégrité finale</small></div></div><h2 style="font-size:17px">📊 Résultats par compétence</h2><table class="result-table"><thead><tr><th>Mission</th><th>XP obtenus</th><th>Défis validés</th><th>Maîtrise</th></tr></thead><tbody>${TITLES.map((t,i)=>`<tr><td>${ICONS[i]} ${escapeHTML(t)}</td><td>${state.missionScores[i]} / ${COUNTS[i]*100}</td><td>${state.missionHits[i]} / ${COUNTS[i]}</td><td class="${state.missionScores[i]>=COUNTS[i]*70?'result-good':'result-warning'}">${pct(state.missionScores[i],COUNTS[i]*100)}%</td></tr>`).join('')}</tbody></table><h2 style="font-size:17px">🎖️ Distinctions</h2><p class="report-notes">${state.badges.map(escapeHTML).join(' · ')}</p><h2 style="font-size:17px">📚 Conseils de révision</h2><ol class="report-notes">${advice.map(s=>`<li>${escapeHTML(s)}</li>`).join('')}</ol><p class="report-notes">Les résultats reflètent les réponses données à des simulations pédagogiques. Ils ne constituent pas une certification officielle et ne prouvent pas l’exécution de vrais tests C# ou pipelines CI/CD.</p><div class="divider"></div><div class="btn-row no-print"><button class="btn btn-primary" data-action="print">🖨️ IMPRIMER / ENREGISTRER EN PDF</button><button class="btn btn-secondary" data-action="restart">↻ RECOMMENCER LE JEU</button></div><p class="fine-print no-print">Sur Chrome ou Edge, choisis « Enregistrer au format PDF » dans la fenêtre d’impression.</p></section>`;}
function toastView(){if(!state.toast)return '';return `<aside class="toast ${state.toast.kind}" role="status" aria-live="polite"><span style="font-size:21px">${state.toast.kind==='good'?'✅':state.toast.kind==='bad'?'⚠️':'💡'}</span><div><strong>${escapeHTML(state.toast.title)}</strong><p>${escapeHTML(state.toast.text)}</p></div><button data-action="close-toast" aria-label="Fermer la notification">×</button></aside>`;}
function render(){APP.innerHTML=header()+`<div class="layout">${sidebar()}<main class="main-area" id="main-content">${state.screen==='intro'?viewIntro():state.screen==='playing'?viewPlaying():state.screen==='missionComplete'?viewMissionComplete():viewResults()}</main></div>`+footer()+toastView();Object.entries(state.formValues||{}).forEach(([id,value])=>{const field=document.getElementById(id);if(field)field.value=value;});}
function handleClick(e){
  const node=e.target.closest('[data-action],[data-card],[data-target],[data-quiz],[data-diagnosis],[data-review],[data-prompt],[data-risk],[data-release-choice]');if(!node)return;
  if(node.dataset.card){state.selectedCard=node.dataset.card;state.toast=null;render();return;}
  if(node.dataset.target){answerSort(node.dataset.target);return;}
  if(node.dataset.quiz!==undefined){answerQuiz(node.dataset.quiz);return;}
  if(node.dataset.diagnosis){answerExperiment(node.dataset.diagnosis);return;}
  if(node.dataset.review!==undefined){answerReview(node.dataset.review);return;}
  if(node.dataset.prompt){if(state.promptSelected.has(node.dataset.prompt))state.promptSelected.delete(node.dataset.prompt);else state.promptSelected.add(node.dataset.prompt);state.toast=null;render();return;}
  if(node.dataset.risk){answerRisk(node.dataset.risk);return;}
  if(node.dataset.releaseChoice){state.releaseChoice=node.dataset.releaseChoice;node.parentElement.querySelectorAll('[data-release-choice]').forEach(x=>x.classList.toggle('active',x===node));return;}
  const action=node.dataset.action;
  if(action==='start'||action==='restart')startGame();
  else if(action==='close-toast'){state.toast=null;document.querySelector('.toast')?.remove();}
  else if(action==='gherkin-check')answerGherkin();
  else if(action==='run-experiment'){state.experimentRan=true;state.toast=null;render();}
  else if(action==='report-check')answerReport();
  else if(action==='prompt-check')answerPrompt();
  else if(action==='next-mission')advanceMission();
  else if(action==='run-release'){state.releaseRan=true;state.toast=null;render();}
  else if(action==='release-check')answerRelease();
  else if(action==='print')window.print();
}
APP.addEventListener('click',handleClick);
APP.addEventListener('change',e=>{const field=e.target;if(field.matches('select[id]'))state.formValues[field.id]=field.value;});
APP.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const card=e.target.closest('[data-card]');if(card){e.preventDefault();card.click();}}});
APP.addEventListener('dragstart',e=>{const card=e.target.closest('[data-card]');if(!card)return;state.selectedCard=card.dataset.card;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',card.dataset.card);requestAnimationFrame(()=>card.classList.add('grabbing'));});
APP.addEventListener('dragover',e=>{const target=e.target.closest('[data-target]');if(!target)return;e.preventDefault();e.dataTransfer.dropEffect='move';target.classList.add('over');});
APP.addEventListener('dragleave',e=>{const target=e.target.closest('[data-target]');if(target&&!target.contains(e.relatedTarget))target.classList.remove('over');});
APP.addEventListener('drop',e=>{const target=e.target.closest('[data-target]');if(!target)return;e.preventDefault();target.classList.remove('over');const id=e.dataTransfer.getData('text/plain');if(id)state.selectedCard=id;answerSort(target.dataset.target);});
APP.addEventListener('dragend',()=>APP.querySelectorAll('.over,.grabbing').forEach(x=>x.classList.remove('over','grabbing')));
runTimer=setInterval(()=>{const timer=document.getElementById('timer');if(timer)timer.textContent=duration(secs());},1000);
render();
